const sampleGuides: Person[] = (() => {
  const usedNames = new Set(people.map(person => person.name))
  return Array.from({ length: 400 }, (_, index) => {
    const city = guideCities[index % guideCities.length]
    const specialty = guideSpecialties[index % guideSpecialties.length]
    const first = guideFirstNames[index % guideFirstNames.length]
    let surnameIndex = (Math.floor(index / guideFirstNames.length) + (index % guideFirstNames.length) * 7) % guideLastNames.length
    let name = `${first} ${guideLastNames[surnameIndex]}`
    while (usedNames.has(name)) {
      surnameIndex = (surnameIndex + 1) % guideLastNames.length
      name = `${first} ${guideLastNames[surnameIndex]}`
    }
    usedNames.add(name)
    return { name, role: specialty.role, country: `${city[0]}, ${city[1]}`, flag: city[2], photo: guidePortraits[index % guidePortraits.length], rating: (4.85 + (index % 15) / 100).toFixed(2), rate: 7 + (index % 12), tags: specialty.tag === 'Culture' ? ['Culture', 'Travel'] : [specialty.tag, 'Culture'], online: index % 4 === 0, verified: index % 3 !== 0, about: `Hi, I’m ${first}, based in ${city[0]}. ${specialty.about}` }
  })
})()
const allPeople: Person[] = [...people, ...sampleGuides]
