type Tab = 'Home' | 'Discover' | 'Messages' | 'My learning' | 'Wallet' | 'Settings' | 'Admin'
type AuthMode = 'sign-in' | 'sign-up' | 'admin'

function AuthPage({ mode, initialRole, onModeChange, onSuccess, onBrowse }: { mode: AuthMode; initialRole: 'Learner' | 'Local guide'; onModeChange: (mode: AuthMode) => void; onSuccess: (role: 'Learner' | 'Local guide' | 'Admin') => void; onBrowse: () => void }) {
  const [name, setName] = useState('')
  const [email, setEmail] = useState('')
  const [password, setPassword] = useState('')
  const [showPassword, setShowPassword] = useState(false)
  const [authError, setAuthError] = useState('')
  const [submitting, setSubmitting] = useState(false)
  const [accountRole, setAccountRole] = useState<'Learner' | 'Local guide'>(initialRole)
  const signingUp = mode === 'sign-up'
  const adminSignIn = mode === 'admin'
  const submit = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault()
    setAuthError('')
    if (adminSignIn) {
      setSubmitting(true)
      try {
        const response = await fetch('/api/auth/admin/sign-in', { method: 'POST', headers: { 'Content-Type': 'application/json' }, credentials: 'include', body: JSON.stringify({ email, password }) })
        const result = await response.json().catch(() => ({})) as { error?: string }
        if (!response.ok) throw new Error(result.error ?? 'Unable to sign in. Check your details and try again.')
        onSuccess('Admin')
      } catch (error) {
        setAuthError(error instanceof Error ? error.message : 'Admin sign in is unavailable right now.')
      } finally {
        setSubmitting(false)
      }
      return
    }
    onSuccess(accountRole)
  }

  return <main className={`auth-page ${adminSignIn ? 'auth-admin-mode' : ''}`}><section className="auth-story"><img className="auth-story-poster" src={img('photo-1529156069898-49953e39b3ac', 1200)} alt="Friends talking together outside"/><video className="auth-story-video" autoPlay loop muted playsInline aria-hidden="true" poster={img('photo-1529156069898-49953e39b3ac', 1200)}><source src="/lootfriends.mp4" type="video/mp4"/></video><div className="auth-story-shade"/><a className="auth-brand" href="#" onClick={event => { event.preventDefault(); onBrowse() }}><span className="brand-mark">L</span><span>LootChat<span className="brand-dot">.</span><small>GOOD PEOPLE. REAL CONVERSATIONS.</small></span></a><div className="auth-story-copy"><span className="auth-story-kicker"><Sparkles size={14}/> A LITTLE CLOSER TO EVERYWHERE</span><h1>Every good thing<br/>starts with <em>hello.</em></h1><p>Meet a local guide, learn something new and feel at home wherever curiosity takes you.</p><div className="auth-proof"><span><Check size={14}/> Start with a free chat</span><span><Check size={14}/> Learn from lived experience</span></div></div><div className="auth-story-foot"><Globe2 size={15}/> Local wisdom, global heart</div></section><section className="auth-form-side"><div className="auth-form-wrap"><button className="auth-back" onClick={onBrowse}><ArrowRight size={14}/> Back to exploring</button><div className="auth-mobile-brand"><span className="brand-mark">L</span><b>LootChat<span className="brand-dot">.</span></b></div><div className="auth-form-heading"><div className="eyebrow">{adminSignIn ? 'SECURE ADMIN ACCESS' : signingUp ? 'YOUR NEXT CHAPTER' : 'WELCOME BACK'}</div><h2>{adminSignIn ? 'Administrator sign in.' : signingUp ? 'Find your people.' : 'Good to have you back.'}</h2><p>{adminSignIn ? 'Sign in to manage member conversations and reply from the shared inbox.' : signingUp ? 'Create your free account and start with a conversation.' : 'Sign in and pick up where curiosity left off.'}</p></div><form className="auth-form" onSubmit={submit}>{signingUp && <label className="auth-field"><span>Your name</span><div><UserRound size={17}/><input autoComplete="name" required value={name} onChange={event => setName(event.target.value)} placeholder="How should we call you?"/></div></label>}<label className="auth-field"><span>Email address</span><div><Mail size={17}/><input type="email" autoComplete="email" required value={email} onChange={event => setEmail(event.target.value)} placeholder={adminSignIn ? 'admin@yourdomain.com' : 'you@example.com'}/></div></label><label className="auth-field"><span>Password</span><div><span className="field-lock">••</span><input type={showPassword ? 'text' : 'password'} autoComplete={signingUp ? 'new-password' : 'current-password'} minLength={8} required value={password} onChange={event => setPassword(event.target.value)} placeholder="At least 8 characters"/><button type="button" aria-label={showPassword ? 'Hide password' : 'Show password'} onClick={() => setShowPassword(!showPassword)}>{showPassword ? <EyeOff size={17}/> : <Eye size={17}/>}</button></div></label>{signingUp && <div className="auth-role"><span>How will you use LootChat?</span><div><button type="button" className={accountRole === 'Learner' ? 'active' : ''} onClick={() => setAccountRole('Learner')}><BookOpen size={16}/><span><b>I’m here to learn</b><small>Meet guides and grow</small></span></button><button type="button" className={accountRole === 'Local guide' ? 'active' : ''} onClick={() => setAccountRole('Local guide')}><Globe2 size={16}/><span><b>I’m a local guide</b><small>Share what you know</small></span></button></div></div>}{authError && <div className="auth-error" role="alert">{authError}</div>}<button className="auth-submit" type="submit" disabled={submitting}>{submitting ? 'Checking details…' : adminSignIn ? 'Sign in to admin' : signingUp ? 'Create free account' : 'Sign in'} <ArrowRight size={16}/></button></form>{!adminSignIn ? <div className="auth-switch">{signingUp ? 'Already have an account?' : 'New to LootChat?'} <button onClick={() => onModeChange(signingUp ? 'sign-in' : 'sign-up')}>{signingUp ? 'Sign in' : 'Create an account'}</button></div> : <div className="auth-switch">Member account? <button onClick={() => onModeChange('sign-in')}>Go to member sign in</button></div>}<div className="auth-preview-note"><ShieldCheck size={15}/><span><b>{adminSignIn ? 'Protected admin session' : 'Prototype preview'}</b><small>{adminSignIn ? 'Your session is stored in an HTTP-only cookie. Admin credentials stay on the server.' : 'Member sign in is simulated locally. Account security and email verification need server setup.'}</small></span></div>{!adminSignIn && <button className="admin-auth-link" onClick={() => onModeChange('admin')}>Administrator? <b>Sign in securely</b> <ArrowRight size={13}/></button>}</div><footer className="auth-footer"><span>© 2026 LootChat</span><span>Made for real conversations</span></footer></section></main>
}

export default function App() {
  const [tab, setTab] = useState<Tab>('Home')
  const [authMode, setAuthMode] = useState<AuthMode | null>(null)
  const [activeName, setActiveName] = useState('Amina Wanjiku')
  const [messages, setMessages] = useState(initialMessages)
  const [adminThreads, setAdminThreads] = useState(initialAdminThreads)
  const [selectedAdminId, setSelectedAdminId] = useState('admin-1')
  const [adminFilter, setAdminFilter] = useState<'All' | 'Needs reply' | 'Replied'>('Needs reply')
  const [adminSearch, setAdminSearch] = useState('')
  const [adminDraft, setAdminDraft] = useState('')
  const [draft, setDraft] = useState('')
  const [search, setSearch] = useState('')
  const [visibleCount, setVisibleCount] = useState(24)
  const [filter, setFilter] = useState('All topics')
  const [countryFilter, setCountryFilter] = useState('All countries')
  const [sortMode, setSortMode] = useState<'loved' | 'online' | 'price'>('loved')
  const [modal, setModal] = useState<'plan' | 'call' | 'profile' | 'notifications' | null>(null)
  const [plan, setPlan] = useState('Premium')
  const [credits, setCredits] = useState(24)
  const [role, setRole] = useState<'Learner' | 'Local guide' | 'Admin'>('Learner')
  const [notice, setNotice] = useState('')
  const [mobileMenu, setMobileMenu] = useState(false)
  const [saved, setSaved] = useState<string[]>([])
  const [chatFilter, setChatFilter] = useState('All')
  const [showPlan, setShowPlan] = useState<'Foreigners' | 'Locals'>('Foreigners')
  const activePerson = allPeople.find(p => p.name === activeName) ?? people[0]
  const activeMessages = messages[activeName] ?? []
  const filteredPeople = useMemo(() => allPeople.filter(p => (filter === 'All topics' || p.tags.includes(filter)) && (countryFilter === 'All countries' || p.country.split(',').pop()?.trim() === countryFilter) && (p.name.toLowerCase().includes(search.toLowerCase()) || p.role.toLowerCase().includes(search.toLowerCase()) || p.country.toLowerCase().includes(search.toLowerCase()))).sort((a, b) => sortMode === 'price' ? a.rate - b.rate || Number(b.rating) - Number(a.rating) : sortMode === 'online' ? Number(Boolean(b.online)) - Number(Boolean(a.online)) || Number(b.rating) - Number(a.rating) : Number(b.rating) - Number(a.rating)), [filter, countryFilter, search, sortMode])
  const visiblePeople = filteredPeople.slice(0, visibleCount)
  const conversationPeople = allPeople.filter(p => messages[p.name])
  const filteredAdminThreads = adminThreads.filter(thread => (adminFilter === 'All' || (adminFilter === 'Needs reply' ? thread.status === 'waiting' : thread.status === 'replied')) && `${thread.name} ${thread.email} ${thread.topic} ${thread.location}`.toLowerCase().includes(adminSearch.toLowerCase()))
  const activeAdminThread = filteredAdminThreads.find(thread => thread.id === selectedAdminId) ?? filteredAdminThreads[0]
  const toast = (s: string) => { setNotice(s); window.setTimeout(() => setNotice(''), 3000) }
  const logout = () => { void fetch('/api/auth/sign-out', { method: 'POST', credentials: 'include' }).catch(() => undefined); setRole('Learner'); setAuthMode('sign-in'); setTab('Home'); setModal(null); setMobileMenu(false); setNotice('') }
  const sendMessage = () => { const text = draft.trim(); if (!text) return; const now = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }); setMessages(prev => ({ ...prev, [activeName]: [...(prev[activeName] ?? []), { text, mine: true, time: now }] })); setDraft('') }
  const sendAdminReply = () => { const text = adminDraft.trim(); if (!text || !activeAdminThread) return; const now = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }); setAdminThreads(prev => prev.map(thread => thread.id === activeAdminThread.id ? { ...thread, status: 'replied', unread: false, updated: 'Just now', messages: [...thread.messages, { id: `reply-${Date.now()}`, text, sender: 'admin', time: now }] } : thread)); setAdminDraft('') }
  const startCall = (kind: 'audio' | 'video') => { if (plan === 'Basic') { setModal('plan'); return } if (credits <= 0) { setModal('plan'); return } setCredits(c => c - 1); setModal('call'); toast(`${kind === 'video' ? 'Video' : 'Audio'} call started · 1 credit used`) }
  const navItems: { label: Tab; icon: typeof MessageCircle; badge?: string }[] = [{ label: 'Home', icon: Globe2 }, { label: 'Discover', icon: Search }, { label: 'Messages', icon: MessageCircle, badge: '3' }, ...(role === 'Admin' ? [{ label: 'Admin' as Tab, icon: ShieldCheck, badge: String(adminThreads.filter(thread => thread.status === 'waiting').length) }] : []), { label: 'My learning', icon: BookOpen }, { label: 'Wallet', icon: Wallet }, { label: 'Settings', icon: Settings }]
  const activate = (name: Tab) => { setTab(name); setMobileMenu(false) }

  useEffect(() => {
    let mounted = true
    fetch('/api/auth/admin/session', { credentials: 'include' }).then(response => response.json()).then(result => {
      if (mounted && result.authenticated) { setRole('Admin'); setTab('Admin') }
    }).catch(() => undefined)
    return () => { mounted = false }
  }, [])

  if (authMode) return <AuthPage mode={authMode} initialRole={role === 'Admin' ? 'Learner' : role} onModeChange={setAuthMode} onBrowse={() => setAuthMode(null)} onSuccess={accountRole => { setRole(accountRole); setAuthMode(null); setTab(accountRole === 'Admin' ? 'Admin' : 'Messages'); toast(accountRole === 'Admin' ? 'Admin session started' : 'Welcome to the LootChat preview') }}/>

  return <div className={`shell ${tab === 'Home' ? 'home-shell' : ''}`}>
    {tab !== 'Home' && <aside className={`sidebar ${mobileMenu ? 'open' : ''}`}>
      <a className="brand" href="#" onClick={e => { e.preventDefault(); activate('Home') }}><span className="brand-mark">L</span><span>LootChat<span className="brand-dot">.</span><small>GOOD PEOPLE. REAL CONVERSATIONS.</small></span></a>
      <div className="side-label">YOUR SPACE</div>
      <nav>{navItems.map(({ label, icon: Icon, badge }) => <button key={label} className={`nav-item ${tab === label ? 'selected' : ''}`} onClick={() => activate(label)}><Icon size={18} strokeWidth={1.8}/><span>{label}</span>{badge && <em>{badge}</em>}</button>)}</nav>
      <div className="side-divider"/><div className="side-label">RECENT CHATS <button className="mini-plus" onClick={() => activate('Discover')}><Plus size={15}/></button></div>
      <div className="recent-list">{people.slice(0, 3).map(p => <button key={p.name} className={`recent ${tab === 'Messages' && activeName === p.name ? 'active' : ''}`} onClick={() => { setActiveName(p.name); activate('Messages') }}><div className="avatar-wrap"><img className="avatar tiny" src={img(p.photo, 72)} alt=""/>{p.online && <i className="online"/>}</div><span className="recent-copy"><b>{p.name.split(' ')[0]} {p.name.split(' ')[1][0]}.</b><small>{p.role}</small></span><span className="recent-time">{p.name === 'Amina Wanjiku' ? '10:30' : 'YEST.'}</span></button>)}</div>
      <div className="sidebar-bottom"><div className="plan-card"><div className="plan-icon"><Sparkles size={15}/></div><div><b>{plan} plan</b><small>{credits} call credits left</small></div><button onClick={() => setModal('plan')} aria-label="Manage plan"><ArrowRight size={16}/></button><div className="credit-progress"><span style={{ width: `${Math.min(100, credits / 30 * 100)}%` }}/></div></div><button className="user-card" onClick={() => setModal('profile')}><img className="avatar tiny" src={img('photo-1534528741775-53994a69daeb', 72)} alt=""/><span><b>Alex Morgan</b><small>{role === 'Learner' ? 'Learner account' : 'Local guide account'}</small></span><MoreHorizontal size={19} className="muted"/></button></div>
    </aside>}
    <main className="main">
      {tab === 'Home' ? <header className="home-topbar"><a className="brand" href="#" onClick={e => { e.preventDefault(); activate('Home') }}><span className="brand-mark">L</span><span>LootChat<span className="brand-dot">.</span><small>GOOD PEOPLE. REAL CONVERSATIONS.</small></span></a><nav><button onClick={() => activate('Discover')}>Explore guides</button><button onClick={() => { setShowPlan('Foreigners'); activate('Wallet') }}>How it works</button><button onClick={() => { setRole('Local guide'); setAuthMode('sign-up') }}>Become a guide</button></nav><button className="home-sign-in" onClick={() => setAuthMode('sign-in')}>Sign in</button><button className="home-nav-cta" onClick={() => setAuthMode('sign-up')}>Get started <ArrowRight size={15}/></button></header> : <header className="topbar"><div className="crumb"><button className="hamburger" onClick={() => setMobileMenu(!mobileMenu)}><Menu size={20}/></button><span>{tab}</span><span className="crumb-slash">/</span><b>{tab === 'Messages' ? 'Your conversations' : tab === 'Discover' ? 'Find your person' : tab === 'Wallet' ? 'Your earnings & credits' : tab === 'My learning' ? 'Your journey' : tab === 'Admin' ? 'Shared support inbox' : 'Your account'}</b></div><div className="top-actions"><span className="top-location"><Globe2 size={14}/> Learning across borders</span><button className="icon-button" onClick={() => setModal('notifications')} aria-label="Notifications"><Bell size={18}/><i className="notif-dot"/></button><button className="top-avatar" onClick={() => setModal('profile')}><img src={img('photo-1534528741775-53994a69daeb', 80)} alt="Alex Morgan"/><ChevronDown size={13}/></button></div></header>}
      {tab === 'Admin' && <section className="admin-page"><div className="admin-page-heading"><div><div className="eyebrow">LOOTCHAT ADMIN WORKSPACE</div><h1>Every conversation,<br/><em>in good hands.</em></h1><p>A shared inbox for member questions, safety reports and account help.</p></div><div className="admin-preview-badge"><span/><div><b>Admin preview</b><small>Replies are local sample data</small></div></div></div><div className="admin-stats"><div className="admin-stat-card"><span><MessageCircle size={16}/> OPEN INBOX</span><b>{adminThreads.length}</b><small>Member conversations</small></div><div className="admin-stat-card attention"><span><Activity size={16}/> NEEDS YOUR REPLY</span><b>{adminThreads.filter(thread => thread.status === 'waiting').length}</b><small>Waiting in the queue</small></div><div className="admin-stat-card"><span><Check size={16}/> REPLIED</span><b>{adminThreads.filter(thread => thread.status === 'replied').length}</b><small>Handled by the team</small></div><div className="admin-stat-card"><span><ShieldCheck size={16}/> SAFETY FIRST</span><b>24/7</b><small>Keep member trust at the center</small></div></div><div className="admin-workspace"><aside className="admin-inbox-panel"><div className="admin-inbox-heading"><div><span>MEMBER INBOX</span><b>All conversations</b></div><span className="admin-total">{adminThreads.length}</span></div><label className="admin-search"><Search size={15}/><input value={adminSearch} onChange={event => setAdminSearch(event.target.value)} placeholder="Search people or topics" aria-label="Search inbox"/><kbd>⌘ K</kbd></label><div className="admin-inbox-filters">{(['Needs reply','All','Replied'] as const).map(mode => <button key={mode} className={adminFilter === mode ? 'active' : ''} onClick={() => setAdminFilter(mode)}>{mode}{mode === 'Needs reply' && <i>{adminThreads.filter(thread => thread.status === 'waiting').length}</i>}</button>)}</div><div className="admin-thread-list">{filteredAdminThreads.map(thread => <button key={thread.id} className={`admin-thread-row ${activeAdminThread?.id === thread.id ? 'selected' : ''}`} onClick={() => { setSelectedAdminId(thread.id); setAdminThreads(prev => prev.map(item => item.id === thread.id ? { ...item, unread: false } : item)) }}><img src={img(thread.photo, 100)} alt=""/><span className="admin-thread-copy"><span className="admin-thread-name"><b>{thread.name}</b><time>{thread.updated}</time></span><small>{thread.topic}</small><span className="admin-thread-preview">{thread.messages[thread.messages.length - 1]?.text}</span></span>{thread.status === 'waiting' && <i className={`admin-status-dot ${thread.unread ? 'unread' : ''}`}/>}</button>)}{filteredAdminThreads.length === 0 && <div className="admin-list-empty">No conversations match this view.</div>}</div><div className="admin-inbox-foot"><ShieldCheck size={14}/> Member conversations are private</div></aside><section className="admin-chat-panel">{activeAdminThread ? <><header className="admin-chat-header"><img src={img(activeAdminThread.photo, 100)} alt=""/><div><h2>{activeAdminThread.name}</h2><p>{activeAdminThread.location} <span>·</span> {activeAdminThread.email}</p></div><span className={`admin-status-pill ${activeAdminThread.status}`}>{activeAdminThread.status === 'waiting' ? 'Needs reply' : 'Replied'}</span></header><div className="admin-thread-context"><span><Sparkles size={14}/></span><div><b>{activeAdminThread.topic}</b><small>{activeAdminThread.status === 'waiting' ? 'This member is waiting for your help.' : 'You’ve replied to this member.'}</small></div></div><div className="admin-messages"><div className="admin-day-divider"><span/>CONVERSATION<span/></div>{activeAdminThread.messages.map(message => <div key={message.id} className={`admin-message-row ${message.sender === 'admin' ? 'from-admin' : ''}`}>{message.sender === 'admin' && <span className="admin-message-avatar">L</span>}<div className="admin-message-stack"><div className="admin-message-bubble">{message.text}</div><small>{message.sender === 'admin' ? 'LootChat support' : activeAdminThread.name} · {message.time}</small></div></div>)}</div><div className="admin-reply-area"><div className="admin-reply-label"><span><ShieldCheck size={14}/> Replying as <b>LootChat support</b></span><button onClick={() => setAdminDraft('Thanks for reaching out. I’m looking into this and will follow up with you here shortly.')}>Insert quick reply</button></div><div className="admin-reply-composer"><textarea value={adminDraft} onChange={event => setAdminDraft(event.target.value)} onKeyDown={event => { if (event.key === 'Enter' && !event.shiftKey) { event.preventDefault(); sendAdminReply() } }} placeholder={`Write a thoughtful reply to ${activeAdminThread.name.split(' ')[0]}...`} rows={2}/><button onClick={sendAdminReply} disabled={!adminDraft.trim()} aria-label="Send admin reply"><Send size={16}/></button></div><div className="admin-reply-hint">Replies are shown as LootChat support <span>↵ to send · shift + ↵ for a new line</span></div></div></> : <div className="admin-empty-state"><MessageCircle size={28}/><b>No conversation selected</b><span>Choose a member conversation to view and reply.</span></div>}</section><aside className="admin-member-panel">{activeAdminThread ? <><div className="admin-member-card"><img src={img(activeAdminThread.photo, 180)} alt=""/><h3>{activeAdminThread.name}</h3><p>{activeAdminThread.location}</p><span className="member-since"><BadgeCheck size={14}/> LootChat member</span></div><div className="admin-member-details"><span>CONVERSATION DETAILS</span><div><small>Topic</small><b>{activeAdminThread.topic}</b></div><div><small>Email</small><b>{activeAdminThread.email}</b></div><div><small>Latest message</small><b>{activeAdminThread.updated}</b></div></div><div className="admin-guidance"><ShieldCheck size={16}/><div><b>Lead with care</b><p>Keep replies kind, clear and useful. For safety reports, follow the review process before closing the conversation.</p></div></div></> : <div className="admin-member-empty">Member details will appear here.</div>}</aside></div><div className="admin-preview-footnote"><ShieldCheck size={14}/> This admin workspace uses sample conversations. Secure admin access, shared inbox storage and message delivery require the server integration.</div></section>}
      {tab === 'Home' && <section className="home-page"><div className="home-hero"><div className="home-copy"><div className="home-kicker"><span/> A LITTLE CLOSER TO EVERYWHERE</div><h1>The world makes<br/>more sense <em>together.</em></h1><p>Meet the people who know a place, a language or a way of life by heart. Start with a free conversation. See where it takes you.</p><div className="home-actions"><button className="home-primary" onClick={() => activate('Discover')}>Find your guide <ArrowRight size={17}/></button><button className="home-secondary" onClick={() => { setActiveName('Amina Wanjiku'); activate('Messages') }}><span className="play-mark">↗</span> See how LootChat works</button></div><div className="home-social"><div className="home-faces">{people.slice(0,3).map(p=><img key={p.name} src={img(p.photo,70)} alt=""/>)}</div><div><b>Good things start with hello.</b><span>Real people. Shared curiosity.</span></div></div></div><div className="home-art"><img className="home-photo-main" src={img('photo-1531206715517-5c0ba140b2b8',900)} alt="Friends sharing a conversation around a table"/><div className="home-photo-shade"/><div className="home-art-note"><span>✳</span><div><b>Stories live here.</b><small>Come curious. Leave connected.</small></div></div><div className="home-floating-card"><span className="home-mini-avatar"><img src={img(people[0].photo,90)} alt=""/><i/></span><span><b>Amina is here</b><small>Swahili · Nairobi, Kenya</small></span><span className="home-rating">★ 4.98</span></div><div className="home-stamp">LOCAL<br/>KNOWLEDGE<br/><i>✳</i> HUMAN<br/>CONNECTION</div></div></div><div className="home-proof"><span><Globe2 size={17}/> LEARN ACROSS CULTURES</span><span><MessageCircle size={17}/> START WITH A FREE CHAT</span><span><Heart size={17}/> LOCAL PEOPLE, FAIR PRICES</span></div><div className="home-section"><div className="home-section-head"><div><div className="eyebrow">A WORLD OF WAYS TO GROW</div><h2>What are you curious about?</h2></div><button className="view-all" onClick={() => activate('Discover')}>Explore every guide <ArrowRight size={15}/></button></div><div className="home-topic-grid">{[{icon:'あ',title:'Speak with confidence',tag:'LANGUAGE',color:'lavender',person:'Amina Wanjiku',place:'Nairobi, Kenya',photo:people[0].photo},{icon:'✳',title:'Find your next move',tag:'CAREER & CRAFT',color:'sand',person:'Kwame Mensah',place:'Accra, Ghana',photo:people[1].photo},{icon:'☼',title:'Make space to grow',tag:'WELLNESS',color:'sage',person:'Zuri Mbeki',place:'Cape Town, SA',photo:people[2].photo}].map(t=><button className={`home-topic ${t.color}`} key={t.title} onClick={() => { setFilter(t.tag==='LANGUAGE'?'Language':t.tag==='WELLNESS'?'Wellness':'Career'); setVisibleCount(24); activate('Discover') }}><span className="topic-symbol">{t.icon}</span><span className="topic-tag">{t.tag}</span><b>{t.title}</b><span className="topic-guide"><img src={img(t.photo,70)} alt=""/> Meet {t.person.split(' ')[0]} <span>· {t.place}</span></span><ArrowUpRight className="topic-arrow" size={17}/></button>)}</div></div><div className="home-quote"><span className="quote-spark">✳</span><div><div className="eyebrow">THE MAGIC IS IN THE MEETING</div><blockquote>“It felt less like learning about a place, and more like being welcomed into it.”</blockquote><span className="quote-byline">A LootChat learner, after a first conversation</span></div><div className="quote-numbers"><b>01</b><span>Curiosity brings us here.<br/>People help us belong.</span></div></div><div className="home-bottom-cta"><div><div className="eyebrow">YOUR NEXT STORY STARTS HERE</div><h2>One hello can open<br/><em>a whole new world.</em></h2></div><button className="home-primary" onClick={() => activate('Discover')}>Meet your person <ArrowRight size={17}/></button><span className="cta-orbit cta-orbit-one"/><span className="cta-orbit cta-orbit-two"/></div><div className="home-footnote"><span>LootChat<span className="brand-dot">.</span> <small>GOOD PEOPLE. REAL CONVERSATIONS.</small></span><span>Built around people, wherever you call home.</span><button onClick={() => toast('Safety center coming soon.')}>Our community values <ArrowRight size={13}/></button></div></section>}
      {tab === 'Messages' && <section className="chat-layout"><div className="chat-list"><div className="chat-list-head"><div><div className="eyebrow">YOUR PEOPLE</div><h1>Conversations<span className="count-pill">{Object.keys(messages).length}</span></h1></div><button className="new-chat" onClick={() => activate('Discover')}><Plus size={16}/> New chat</button></div><div className="chat-search"><Search size={16}/><input placeholder="Search conversations" value={search} onChange={e => { setSearch(e.target.value); setVisibleCount(24) }}/><kbd>⌘ K</kbd></div><div className="chat-filters">{['All', 'Unread', 'Online'].map(f => <button key={f} className={chatFilter === f ? 'on' : ''} onClick={() => setChatFilter(f)}>{f}</button>)}</div><div className="chat-items">{conversationPeople.filter(p => p.name.toLowerCase().includes(search.toLowerCase()) && (chatFilter !== 'Online' || p.online) && (chatFilter !== 'Unread' || p.name !== 'Zuri Mbeki' && p.name !== 'Nia Okafor')).map((p, i) => <button key={p.name} className={`chat-item ${p.name === activeName ? 'chosen' : ''}`} onClick={() => setActiveName(p.name)}><div className="avatar-wrap"><img className="avatar" src={img(p.photo, 104)} alt=""/>{p.online && <i className="online"/>}</div><span className="chat-item-info"><span className="chat-name"><b>{p.name}</b><time>{i === 0 ? '10:30' : i === 1 ? '9:14' : 'YEST.'}</time></span><span className="chat-preview">{(messages[p.name] ?? []).slice(-1)[0]?.text}</span><span className="chat-context"><span>{p.tags[0]}</span>{i === 0 && <i className="unread-dot"/>}</span></span></button>)}</div><div className="chat-list-bottom"><ShieldCheck size={15}/> Your conversations are private and secure</div></div>
        <div className="conversation"><div className="conversation-head"><div className="contact"><div className="avatar-wrap"><img className="avatar medium" src={img(activePerson.photo, 112)} alt=""/>{activePerson.online && <i className="online"/>}</div><div><h2>{activePerson.name} {activePerson.verified && <BadgeCheck size={17} className="verified" fill="currentColor"/>}</h2><p>{activePerson.flag} &nbsp;{activePerson.role} <span className="head-dot">·</span> <span className="status-text">{activePerson.online ? 'Online now' : 'Replies within a day'}</span></p></div></div><div className="conv-actions"><button className="call-button" onClick={() => startCall('audio')}><Headphones size={17}/><span>Audio</span><small>1 cr</small></button><button className="call-button video-button" onClick={() => startCall('video')}><Video size={17}/><span>Video</span><small>1 cr</small></button><button className="icon-button more-button" onClick={() => setModal('profile')}><MoreHorizontal size={20}/></button></div></div><div className="session-banner"><span className="banner-spark"><Sparkles size={14}/></span><span><b>Good conversations start here.</b> Chat is always free. Hop on a call when you’re ready.</span><button onClick={() => setModal('plan')}>How credits work <ArrowRight size={14}/></button></div><div className="messages-area"><div className="day-divider"><span/>TODAY<span/></div>{activeMessages.map((m, i) => <div className={`message-row ${m.mine ? 'mine' : ''}`} key={i}>{!m.mine && <img className="avatar msg-avatar" src={img(activePerson.photo, 72)} alt=""/>}<div className="message-stack"><div className="bubble">{m.text}</div><div className="message-meta">{m.time}{m.mine && <span className="read-receipt">✓✓</span>}</div></div></div>)}{activeMessages.length < 3 && <div className="prompt-card"><span className="prompt-icon"><Sparkles size={15}/></span><span><b>Pick up where you left off</b><small>Ask about {activePerson.tags[0].toLowerCase()}, their hometown or what you’d like to learn.</small></span><button onClick={() => setDraft(`What should I know about ${activePerson.country.split(',')[0]}?`)}>Try a prompt <ArrowRight size={14}/></button></div>}</div><div className="composer"><div className="composer-wrap"><button className="attach" onClick={() => toast('Media sharing will be available soon.')} aria-label="Attach file"><Plus size={19}/></button><textarea value={draft} onChange={e => setDraft(e.target.value)} onKeyDown={e => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); sendMessage() } }} placeholder={`Write a message to ${activePerson.name.split(' ')[0]}...`} rows={1}/><span className="free-tag">FREE CHAT</span><button className="send-button" onClick={sendMessage} disabled={!draft.trim()} aria-label="Send message"><Send size={16}/></button></div><div className="composer-help"><span><ShieldCheck size={13}/> Conversations stay between you two</span><span>Press <kbd>↵</kbd> to send</span></div></div></div></section>}
      {tab === 'Discover' && <section className="page-content"><div className="discover-hero"><div><div className="eyebrow">A WORLD OF WISDOM</div><h1>Learn from the<br/><em>people who live it.</em></h1><p>One good conversation can take you somewhere new.</p></div><div className="hero-illustration"><span>🌍</span><i>✦</i><b>YOUR NEXT<br/>CHAPTER</b></div></div><div className="guide-filter-panel"><div className="filter-panel-top"><div className="filter-title"><span><SlidersHorizontal size={16}/></span><div><b>Find your kind of conversation</b><small>Search by name, topic or place</small></div></div><div className="filter-results">{filteredPeople.length} guides</div>{(filter !== 'All topics' || countryFilter !== 'All countries' || search) && <button className="clear-filters" onClick={() => { setFilter('All topics'); setCountryFilter('All countries'); setSearch(''); setSortMode('loved'); setVisibleCount(24) }}>Clear filters <X size={13}/></button>}</div><div className="filter-control-row"><label className="filter-search"><Search size={17}/><input aria-label="Search guides" placeholder="Try ‘Swahili’, ‘food’, or a city..." value={search} onChange={e => { setSearch(e.target.value); setVisibleCount(24) }}/><kbd>⌘ K</kbd></label><label className="filter-select-wrap"><Globe2 size={15}/><select aria-label="Choose a country" value={countryFilter} onChange={e => { setCountryFilter(e.target.value); setVisibleCount(24) }}><option value="All countries">Everywhere</option>{guideCountries.map(country => <option key={country} value={country}>{guideCountryFlags.get(country)} {country}</option>)}</select><ChevronDown size={14}/></label><label className="filter-select-wrap sort-select"><span className="sort-label">SORT</span><select aria-label="Sort guides" value={sortMode} onChange={e => { setSortMode(e.target.value as 'loved' | 'online' | 'price'); setVisibleCount(24) }}><option value="loved">Most loved</option><option value="online">Online now</option><option value="price">Price: low to high</option></select><ChevronDown size={14}/></label></div><div className="topic-filter-row"><span className="topic-filter-label">EXPLORE</span>{['All topics','Language','Culture','Career','Business','Wellness','Creative','Food','Travel'].map(topic => <button key={topic} className={`topic-filter ${filter === topic ? 'selected' : ''}`} onClick={() => { setFilter(topic); setVisibleCount(24) }}>{topic}</button>)}</div></div><div className="section-heading"><div><div className="eyebrow">GOOD PEOPLE, GREAT CONVERSATIONS</div><h2>Find your person <span>({filteredPeople.length})</span></h2><p className="guide-sample-note">Preview community · sample profiles across 80 cities</p></div><button className="view-all" onClick={() => toast('You’re seeing all available guides.')}>View all <ArrowRight size={15}/></button></div><div className="people-grid">{visiblePeople.map(p => <article className="person-card" key={p.name}><div className="person-photo"><img src={img(p.photo, 640)} alt={p.name} loading="lazy"/><button className={`heart-button ${saved.includes(p.name) ? 'hearted' : ''}`} aria-label="Save guide" onClick={() => setSaved(s => s.includes(p.name) ? s.filter(x => x !== p.name) : [...s, p.name])}><Heart size={18} fill={saved.includes(p.name) ? 'currentColor' : 'none'}/></button>{p.online && <span className="online-label"><i/> HERE NOW</span>}</div><div className="person-card-body"><div className="person-title"><h3>{p.name} {p.verified && <BadgeCheck size={16} className="verified" fill="currentColor"/>}</h3><span>★ {p.rating}</span></div><div className="person-role">{p.role}</div><div className="person-location">{p.flag} &nbsp;{p.country}</div><p>{p.about}</p><div className="tag-list">{p.tags.map(t => <span key={t}>{t}</span>)}</div><div className="person-card-foot"><span>from <b>${p.rate}</b><small> / chat</small></span><button onClick={() => { setActiveName(p.name); setMessages(prev => prev[p.name] ? prev : { ...prev, [p.name]: [{ text: `Hi! I’d love to hear more about life in ${p.country.split(',')[0]}.`, mine: true, time: 'Now' }] }); setTab('Messages') }}>Say hello <ArrowRight size={14}/></button></div></div></article>)}</div>{visibleCount < filteredPeople.length && <div className="load-more-wrap"><button className="load-more" onClick={() => setVisibleCount(n => Math.min(n + 24, filteredPeople.length))}>Show more guides <span>{filteredPeople.length - visibleCount} more</span><ArrowDown size={15}/></button></div>}<div className="trust-strip"><div><ShieldCheck size={19}/><b>Real people, real experience</b><span>Every local guide is verified by our team.</span></div><div><Globe2 size={19}/><b>Learn on your terms</b><span>Start free. Book a call when you’re ready.</span></div><div><Heart size={19}/><b>Fair for everyone</b><span>Locals set their rates and keep more.</span></div></div></section>}
      {tab === 'Wallet' && <section className="page-content"><div className="eyebrow">YOUR ACCOUNT</div><h1 className="page-title">A little goes a long way.</h1><p className="page-subtitle">Clear pricing for both sides of the conversation.</p><div className="wallet-overview"><div><span>AVAILABLE CALL CREDITS</span><strong>{credits}<small> credits</small></strong><p>Chat is always free. Calls use 1 credit per minute.</p><button onClick={() => setModal('plan')}>Get more credits <ArrowRight size={15}/></button></div><div className="wallet-icon"><Wallet size={35}/></div></div><div className="section-heading plan-heading"><div><div className="eyebrow">MADE FOR YOUR JOURNEY</div><h2>Simple plans, both sides.</h2></div><div className="role-toggle"><button className={showPlan === 'Foreigners' ? 'active' : ''} onClick={() => setShowPlan('Foreigners')}>Learner</button><button className={showPlan === 'Locals' ? 'active' : ''} onClick={() => setShowPlan('Locals')}>Local guide</button></div></div><div className="plans-grid">{plans.map((p, i) => <div className={`plan-option ${p.color} ${plan === p.name ? 'current' : ''}`} key={p.name}>{i === 1 && <div className="popular-label">MOST LOVED</div>}<div className="plan-heading-small"><span>{p.name}</span>{plan === p.name && <span className="your-plan"><Check size={12}/> CURRENT</span>}</div><div className="price">{showPlan === 'Locals' ? p.local.split(' ·')[0] : p.price}<small>{showPlan === 'Locals' ? '' : i === 0 ? '' : ' / month'}</small></div><p>{p.note}</p><div className="plan-sep"/>{p.items.map(it => <div className="plan-feature" key={it}><Check size={15}/>{it}</div>)}<button className="plan-cta" onClick={() => { setPlan(p.name); setCredits(i === 2 ? 100 : i === 1 ? 30 : 0); toast(`${p.name} plan selected`) }}>{plan === p.name ? 'Your current plan' : i === 0 ? 'Get started free' : `Choose ${p.name}`}</button></div>)}</div><p className="fee-note"><ShieldCheck size={15}/> Learners pay monthly for calls. Local guides pay a lower membership and a small fee on each paid conversation. Chat is always free.</p></section>}
      {tab === 'My learning' && <section className="page-content"><div className="eyebrow">YOUR LEARNING PATH</div><h1 className="page-title">Curiosity looks good on you.</h1><p className="page-subtitle">Your conversations are becoming something meaningful.</p><div className="journey-stats"><div><span>PEOPLE YOU’VE MET</span><strong>4</strong><small>Across 3 countries</small></div><div><span>TIME SPENT LEARNING</span><strong>6.5 <i>hrs</i></strong><small>Every minute counts</small></div><div><span>YOUR CURIOSITY</span><strong>12 <i>chats</i></strong><small>And counting</small></div></div><div className="section-heading journey-heading"><div><div className="eyebrow">KEEP THE MOMENTUM</div><h2>People in your world</h2></div><button className="view-all" onClick={() => activate('Discover')}>Meet someone new <ArrowRight size={15}/></button></div><div className="journey-list">{people.slice(0, 3).map((p, i) => <div className="journey-row" key={p.name}><img className="avatar medium" src={img(p.photo, 112)} alt=""/><div className="journey-person"><b>{p.name} {p.verified && <BadgeCheck size={15} className="verified" fill="currentColor"/>}</b><span>{p.role} · {p.flag} {p.country}</span></div><div className="journey-progress"><span>{i === 0 ? '3' : i === 1 ? '2' : '1'} conversations</span><div><i style={{ width: `${80 - i * 20}%` }}/></div></div><button className="outline-button" onClick={() => { setActiveName(p.name); setTab('Messages') }}>Continue chat <ArrowRight size={14}/></button></div>)}</div><div className="learning-tip"><span>✦</span><div><b>Little tip from us</b><p>Ask about the things you won’t find in a guidebook. That’s where the good stuff lives.</p></div></div></section>}
      {tab === 'Settings' && <section className="page-content settings-content"><div className="eyebrow">YOUR ACCOUNT</div><h1 className="page-title">Make yourself at home.</h1><p className="page-subtitle">Set up your space and how you want to show up.</p><div className="settings-card profile-settings"><img className="profile-large" src={img('photo-1534528741775-53994a69daeb', 160)} alt="Alex Morgan"/><div><h2>Alex Morgan <BadgeCheck size={16} className="verified" fill="currentColor"/></h2><p>alex.morgan@email.com · Nairobi, Kenya 🇰🇪</p><button className="outline-button" onClick={() => toast('Profile editing will be available soon.')}>Edit profile <ArrowRight size={14}/></button></div><button className="role-switch" onClick={() => setRole(role === 'Learner' ? 'Local guide' : 'Learner')}><span>ACCOUNT TYPE</span><b>{role} <ChevronDown size={14}/></b><small>Switch your account</small></button></div><div className="settings-columns"><div className="settings-card"><div className="eyebrow">ACCOUNT PREFERENCES</div><h3>Your space, your way.</h3>{[{i:Bell,t:'Notifications',s:'Choose what you hear about'},{i:ShieldCheck,t:'Privacy & safety',s:'Manage your account security'},{i:CreditCard,t:'Payments',s:'Your plans and payment methods'}].map(({i:Icon,t,s})=><button className="setting-row" key={t} onClick={() => t === 'Payments' ? setModal('plan') : toast(`${t} settings coming soon`)}><Icon size={17}/><span><b>{t}</b><small>{s}</small></span><ArrowRight size={15}/></button>)}</div><div className="settings-card account-side"><div className="eyebrow">HERE TO HELP</div><h3>We’re people people.</h3><p>Something on your mind? We’re always up for a chat.</p><button className="support-button" onClick={() => toast('Say hello at hello@lootchat.com')}>Talk to our team <ArrowRight size={14}/></button><button className="admin-preview-link" onClick={() => setAuthMode('admin')}><ShieldCheck size={15}/><span><b>Administrator sign in</b><small>Secure access to the member inbox</small></span><ArrowRight size={14}/></button><button className="logout-button" onClick={logout}> <LogOut size={15}/> Sign out</button></div></div></section>}
      <footer className="footer"><span>© 2026 LootChat. Made with <Heart size={12} fill="currentColor"/> across borders.</span><div><button onClick={() => toast('Safety center coming soon.')}>Safety center</button><button onClick={() => toast('Support: hello@lootchat.com')}>Get help</button><span>English <ChevronDown size={12}/></span></div></footer>
    </main>
    {notice && <div className="toast"><Check size={16}/>{notice}</div>}
    {modal && <div className="modal-backdrop" onClick={() => setModal(null)}><div className={`modal ${modal === 'call' ? 'call-modal' : ''}`} onClick={e => e.stopPropagation()}><button className="modal-close" onClick={() => setModal(null)}><X size={18}/></button>{modal === 'plan' && <><div className="modal-icon"><Sparkles size={21}/></div><div className="eyebrow">A LITTLE MORE YOU-TIME</div><h2>Call credits, made simple.</h2><p className="modal-copy">Keep chatting for free, anytime. Your Premium plan gives you 30 call minutes each month. One credit = one minute in an audio or video call.</p><div className="credit-summary"><span><Activity size={17}/> YOUR BALANCE</span><b>{credits} <small>credits</small></b></div><div className="modal-features"><span><Check size={15}/> Chat never uses credits</span><span><Check size={15}/> You choose when a call starts</span><span><Check size={15}/> Your balance is always visible</span></div><button className="modal-primary" onClick={() => { setModal(null); setTab('Wallet') }}>Explore plans <ArrowRight size={16}/></button><button className="modal-secondary" onClick={() => setModal(null)}>Maybe later</button></>}{modal === 'call' && <><div className="call-orbit"><img src={img(activePerson.photo, 140)} alt=""/><span><Activity size={18}/></span></div><div className="eyebrow">YOUR CONVERSATION IS STARTING</div><h2>Connecting with {activePerson.name.split(' ')[0]}</h2><p className="modal-copy">Your call is ready. You’re using 1 credit per minute.</p><div className="call-credit-note"><Wallet size={16}/> {credits} credits left after this call</div><button className="modal-primary" onClick={() => setModal(null)}>Got it <ArrowRight size={15}/></button></>}{modal === 'profile' && <><div className="profile-modal-head"><img className="profile-large" src={img(activePerson.photo, 160)} alt=""/><span><h2>{activePerson.name}</h2><p>{activePerson.role} · {activePerson.flag}</p></span></div><div className="profile-detail"><b>About</b><p>{activePerson.about}</p></div><div className="profile-detail"><b>Conversation rate</b><p>${activePerson.rate} / chat · Calls use 1 credit per minute</p></div><button className="modal-primary" onClick={() => { setModal(null); setTab('Discover') }}>Explore local guides <ArrowRight size={15}/></button></>}{modal === 'notifications' && <><div className="modal-icon"><Bell size={20}/></div><div className="eyebrow">YOUR INBOX</div><h2>A little quiet, for now.</h2><p className="modal-copy">You’re all caught up. When someone writes back, we’ll let you know.</p><button className="modal-primary" onClick={() => setModal(null)}>Sounds good <Check size={15}/></button></>}</div></div>}
    <button className="help-float" onClick={() => toast('We’re here for you · hello@lootchat.com')}><CircleHelp size={17}/></button>
  </div>
}
